    id: 'art-006',
    title: 'The Archipelagic Imperative: Why Localized Disaster Governance Can No Longer Wait',
    category: 'Ink & Opinion',
    kind: 'OPINION',
    author: 'Axel Domingo',
    authorRole: 'Senior Fellow, Philippine Institute for Development Studies',
    date: '2026-09-24',
